// Сценарии эталона actions.cjs, rebase.cjs, restore.cjs, init.cjs, clone.cjs.
// Подготовка: git/gitIn, write, writeBytes, rm, mkdir. Шаги: { action, payload } | { call, ... } | { git: [...] } | { write: [файл, текст] } | { rm: файл } | { read: файл }.
// В шагах {{rev:X}} заменяется хэшем, {{TMP}} — временной папкой сценария, {{TMPURL}} — её адресом file://.

const commitAll = (message) => [['git', 'add', '-A'], ['git', 'commit', '-q', '-m', message]];
